sgtitle(tiled, {"{\textbf{Run Wk22-02-04 (Conc. Target $H_2$ 20 vol.$\%$)}}",'LU vs Kistler DAQs (Flush Mounted Pressure Sensors)'}, 'Interpreter', 'latex'); %[output:50cf559d]
% close all
%[text] ## Multi-Plot (Pressure)
% Plot four runs in a 2x2 tiled layout, each tile with its own left/right yyaxis
runs = { run_Wk22_02_01, run_Wk22_02_02, run_Wk22_02_03, run_Wk22_02_04 };
h2VolPct = [18, 18, 20, 20];
daq4PressureNames = ["P7_7061B", "P3_7061B"];
daq4TriggerName = "5280A_TriggerIn";
nRuns = numel(runs);

padFrac = 0.20;  % 20% padding per tile

figure('Units','centimeters','Position',[10 10 18 12]);
t = tiledlayout(2,2,'TileSpacing','compact','Padding','compact');
set(gcf,'Color','w');

for k = 1:nRuns
    runK = runs{k};

    % safety checks
    if isempty(runK) || ~isfield(runK,'DAQ_1') || ~isfield(runK,'DAQ_4')
        warning('Run %d data missing - skipping tile.', k);
        continue;
    end

    % extract signals
    t1 = runK.DAQ_1.t_s;
    y1_p = runK.DAQ_1.signal(:,1);   % pressure DAQ-1
    y1_tr = runK.DAQ_1.signal(:,2);  % trigger DAQ-1

    idxP4 = find(ismember(runK.DAQ_4.channels, daq4PressureNames), 1);
    idxT4 = find(runK.DAQ_4.channels == daq4TriggerName, 1);
    if isempty(idxP4) || isempty(idxT4)
        warning('Run %d DAQ-4 pressure/trigger channel not found - skipping tile.', k);
        continue;
    end
    t2 = runK.DAQ_4.t_s;
    y2_p = runK.DAQ_4.signal(:,idxP4);   % pressure DAQ-4
    y2_tr = runK.DAQ_4.signal(:,idxT4);  % trigger DAQ-4

    % compute per-tile ranges combining DAQ_1 and DAQ_4 for each axis
    % Time range
    tAll = [t1(:); t2(:)];
    tMin = min(tAll); tMax = max(tAll);
    tRange = tMax - tMin;
    if tRange == 0
        tPad = abs(tMin)*padFrac + 1e-3;
    else
        tPad = tRange * padFrac;
    end
    xLimTile = [tMin - tPad, tMax + tPad];

    % Pressure (left axis) range (kPa)
    pAll = [y1_p(:); y2_p(:)];
    pMin = min(pAll); pMax = max(pAll);
    pRange = pMax - pMin;
    if pRange == 0
        pPad = abs(pMin)*padFrac + 1e-3;
    else
        pPad = pRange * padFrac;
    end
    yLimPressureTile = [pMin - pPad, pMax + pPad];

    % Trigger (right axis) range (V)
    trAll = [y1_tr(:); y2_tr(:)];
    trMin = min(trAll); trMax = max(trAll);
    trRange = trMax - trMin;
    if trRange == 0
        trPad = abs(trMin)*padFrac + 1e-3;
    else
        trPad = trRange * padFrac;
    end
    yLimTriggerTile = [trMin - trPad, trMax + trPad];

    % Now plot in this tile
    ax = nexttile;

    % Left axis: pressures
    yyaxis(ax, 'left');
    hP1 = plot(ax, t1, y1_p, '-', 'Color', LUBlue,   'LineWidth', 0.7); hold(ax,'on');
    hP2 = plot(ax, t2, y2_p, '-', 'Color', LUCopper, 'LineWidth', 0.7);
    ylabel(ax, 'Overpressure [kPa]', 'Interpreter','latex');
    ax.YColor = 'k';
    ylim(ax, yLimPressureTile);  % per-tile left limits

    % Right axis: triggers
    yyaxis(ax, 'right');
    hT1 = plot(ax, t1, y1_tr, '-', 'Color', LUBlue_Light,   'LineWidth', 0.7);
    hT2 = plot(ax, t2, y2_tr, '-', 'Color', LUCopper_Light, 'LineWidth', 0.7);
    ylabel(ax, 'Trigger Voltage [V]', 'Interpreter','latex');
    ax.YColor = LUBlue_Light;
    ylim(ax, yLimTriggerTile);   % per-tile right limits

    % x limits (per-tile)
    xlim(ax, xLimTile);

    xlabel(ax, 'Time [s]', 'Interpreter','latex');

    % Title and legend
    runName = sprintf('Run Wk22-02-0%d', k);
    ttl = { sprintf('%s ( $H_2$ %g vol.\\%% )', runName, h2VolPct(k)), ...
            'Pressure (Flush Mounted Sensors) and Trigger Signal' };
    title(ax, ttl, 'Interpreter','latex');

    legend(ax, [hP1, hP2, hT1, hT2], ...
        {'Pressure (DAQ-1)','Pressure (DAQ-4)','Trigger (DAQ-1)','Trigger (DAQ-4)'}, ...
        'Location','northeast', 'Interpreter','latex');

    grid(ax,'on');
    hold(ax,'off');
end

sgtitle(t, 'Group VH2D-Wk22-02: Pressure $\&$ Trigger ', 'Interpreter','latex');
ax = gca;
pbaspect(ax, [16 9 1]);


