    figure;
    x0 = 10; y0 = 10; width = 28; height = 22;
    set(gcf, 'units', 'centimeters', 'position', [x0, y0, width, height]);
    sgtitle({ ...
        'Tunnel Hydrogen Deflagration Experiments'; ...
        sprintf('All Channels - %s', daqData.fileName) ...
        }, 'Interpreter', 'latex');

    for chIdx = 1:4
        ax = subplot(4,1,chIdx);

        if chIdx == 4
            thisColor = Red_Dark;
